begin;
do $$
declare owner_id uuid; g uuid:=gen_random_uuid(); t uuid:=gen_random_uuid(); m uuid:=gen_random_uuid(); p uuid:=gen_random_uuid(); tok text:=encode(extensions.gen_random_bytes(32),'hex'); result jsonb; before_payload jsonb; accesses bigint;
begin
 select id into owner_id from auth.users where email_confirmed_at is not null and not coalesce(is_anonymous,false) order by created_at limit 1;
 perform set_config('request.jwt.claim.sub',owner_id::text,true);
 insert into public.travel_groups(id,owner_id,name) values(g,owner_id,'Preview rollback');
 insert into public.trips(id,group_id,organizer_id,name,event_type) values(t,g,owner_id,'Natal da família','celebration');
 insert into public.group_members(id,group_id,display_name,created_by) values(m,g,'Private participant',owner_id);
 insert into public.trip_participants(id,trip_id,member_id,local_source_id) values(p,t,m,'preview-fixture');
 before_payload:='{"trip":{"eventType":"event","coverImage":"data:image/png;base64,iVBORw0KGgo=","address":"SECRET address"},"payments":[{"amountCents":999}],"people":[{"email":"SECRET email"}]}';
 insert into public.trip_snapshots(trip_id,payload,updated_by) values(t,before_payload,owner_id);
 insert into public.trip_join_links(trip_id,token_hash,created_by) values(t,encode(extensions.digest(tok,'sha256'),'hex'),owner_id);
 select count(*) into accesses from public.trip_access where trip_id=t;
 perform set_config('request.jwt.claim.sub','',true);
 result:=public.get_invite_social_preview(tok,'join');
 if result->>'name'<>'Natal da família' or result->>'kind'<>'evento' or result->>'cover_image'<>'data:image/png;base64,iVBORw0KGgo=' then raise exception 'metadata missing';end if;
 if (select count(*) from jsonb_object_keys(result))<>4 or result::text like '%SECRET%' then raise exception 'private data exposed';end if;
 if public.get_invite_social_preview('bad','join')->>'status'<>'invalid' or public.get_invite_social_preview(tok,'access')->>'status'<>'invalid' then raise exception 'invalid token accepted';end if;
 update public.trip_join_links set active=false where trip_id=t;
 if public.get_invite_social_preview(tok,'join')->>'status'<>'invalid' then raise exception 'revoked join disclosed';end if;
 insert into public.participant_access_links(trip_id,participant_id,token_hash,created_by) values(t,p,encode(extensions.digest(tok,'sha256'),'hex'),owner_id);
 result:=public.get_invite_social_preview(tok,'access');
 if result->>'status'<>'available' or public.get_invite_social_preview(tok,'join')->>'status'<>'available' then raise exception 'access or legacy missing';end if;
 update public.participant_access_links set status='requested' where trip_id=t;
 if public.get_invite_social_preview(tok,'access')->>'status'<>'available' then raise exception 'requested unavailable';end if;
 update public.participant_access_links set status='approved' where trip_id=t;
 if public.get_invite_social_preview(tok,'access')->>'status'<>'available' then raise exception 'approved unavailable';end if;
 update public.participant_access_links set expires_at=now()-interval '1 minute' where trip_id=t;
 if public.get_invite_social_preview(tok,'access')->>'status'<>'invalid' then raise exception 'expired disclosed';end if;
 update public.participant_access_links set expires_at=now()+interval '1 day',status='cancelled' where trip_id=t;
 if public.get_invite_social_preview(tok,'access')->>'status'<>'invalid' then raise exception 'cancelled disclosed';end if;
 update public.participant_access_links set status='open' where trip_id=t;
 update public.trip_participants set removed_at=now() where id=p;
 if public.get_invite_social_preview(tok,'access')->>'status'<>'invalid' then raise exception 'removed participant disclosed';end if;
 update public.trip_participants set removed_at=null where id=p;
 insert into public.trip_invites(trip_id,participant_id,role,token_hash,expires_at,created_by) values(t,p,'participant',encode(extensions.digest(tok,'sha256'),'hex'),now()+interval '1 day',owner_id);
 if public.get_invite_social_preview(tok,'invite')->>'status'<>'available' then raise exception 'legacy invitation unavailable';end if;
 update public.trip_invites set status='accepted' where trip_id=t;
 if public.get_invite_social_preview(tok,'invite')->>'status'<>'invalid' then raise exception 'consumed invitation disclosed';end if;
 if (select payload from public.trip_snapshots where trip_id=t)<>before_payload or (select count(*) from public.trip_participants where trip_id=t)<>1 or (select count(*) from public.trip_access where trip_id=t)<>accesses then raise exception 'preview changed planning';end if;
 if not has_function_privilege('anon','public.get_invite_social_preview(text,text)','execute') then raise exception 'crawler cannot read';end if;
 raise notice 'PASS token-scoped metadata, privacy, no acceptance/financial mutation, expiration/revocation, individual and legacy invitations';
end $$;
rollback;
